// PacketTunnelProvider.swift
// The actual VPN engine on iOS: an NEPacketTunnelProvider hosting an
// in-process sing-box instance (Libbox.xcframework, built by
// scripts/build-libbox.sh). Replaces the desktop xray/hysteria/tun2socks
// process chain — iOS does not allow spawning processes or editing routes.
//
// The sing-box JSON config is generated by the Rust core
// (src-tauri/src/singbox.rs) and arrives via
// NETunnelProviderProtocol.providerConfiguration["config"].
//
// NOTE: written against the sing-box v1.12.x libbox API (the version pinned
// in scripts/build-libbox.sh). If you bump sing-box and Xcode reports
// protocol-conformance errors here, align the method signatures with
// sing-box-for-apple (ApplicationLibrary/ExtensionProvider.swift and
// ExtensionPlatformInterface.swift) at the same version tag.

import Foundation
import Libbox
import Network
import NetworkExtension
import os.log

private let tunnelLog = OSLog(subsystem: "com.proxysvpn.desktop.PacketTunnel", category: "Tunnel")

class PacketTunnelProvider: NEPacketTunnelProvider {
    private var boxService: LibboxBoxService?
    private var platformInterface: PlatformInterface?

    override func startTunnel(options _: [String: NSObject]?, completionHandler: @escaping (Error?) -> Void) {
        guard let proto = protocolConfiguration as? NETunnelProviderProtocol,
              let config = proto.providerConfiguration?["config"] as? String
        else {
            completionHandler(NSError(
                domain: "ProxysVPN", code: 1,
                userInfo: [NSLocalizedDescriptionKey: "missing sing-box config in provider configuration"]
            ))
            return
        }

        let fm = FileManager.default
        let baseDir = fm.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("sing-box", isDirectory: true)
        let cacheDir = fm.urls(for: .cachesDirectory, in: .userDomainMask)[0]
        try? fm.createDirectory(at: baseDir, withIntermediateDirectories: true)

        let setupOptions = LibboxSetupOptions()
        setupOptions.basePath = baseDir.relativePath
        setupOptions.workingPath = baseDir.relativePath
        setupOptions.tempPath = cacheDir.relativePath
        var error: NSError?
        LibboxSetup(setupOptions, &error)
        if let error {
            completionHandler(error)
            return
        }

        let iface = PlatformInterface(provider: self)
        platformInterface = iface

        // A C function with NSError** is not imported as `throws`.
        var serviceError: NSError?
        guard let service = LibboxNewService(config, iface, &serviceError) else {
            let failure = serviceError ?? NSError(
                domain: "ProxysVPN", code: 6,
                userInfo: [NSLocalizedDescriptionKey: "sing-box service was not created"]
            )
            os_log("sing-box start failed: %{public}@", log: tunnelLog, type: .error,
                   failure.localizedDescription)
            completionHandler(failure)
            return
        }
        do {
            try service.start()
            boxService = service
            os_log("sing-box started", log: tunnelLog, type: .info)
            completionHandler(nil)
        } catch {
            os_log("sing-box start failed: %{public}@", log: tunnelLog, type: .error,
                   error.localizedDescription)
            completionHandler(error)
        }
    }

    override func stopTunnel(with _: NEProviderStopReason, completionHandler: @escaping () -> Void) {
        if let service = boxService {
            do {
                try service.close()
            } catch {
                os_log("sing-box close failed: %{public}@", log: tunnelLog, type: .error,
                       error.localizedDescription)
            }
            boxService = nil
        }
        platformInterface?.shutdown()
        platformInterface = nil
        completionHandler()
    }

    override func sleep(completionHandler: @escaping () -> Void) {
        boxService?.pause()
        completionHandler()
    }

    override func wake() {
        boxService?.wake()
    }
}

// MARK: - Libbox platform interface

private final class PlatformInterface: NSObject, LibboxPlatformInterfaceProtocol {
    private weak var provider: PacketTunnelProvider?
    private var networkMonitor: NWPathMonitor?

    init(provider: PacketTunnelProvider) {
        self.provider = provider
    }

    func shutdown() {
        networkMonitor?.cancel()
        networkMonitor = nil
    }

    // MARK: TUN

    func openTun(_ options: LibboxTunOptionsProtocol?, ret0_: UnsafeMutablePointer<Int32>?) throws {
        guard let options, let provider else {
            throw NSError(domain: "ProxysVPN", code: 2,
                          userInfo: [NSLocalizedDescriptionKey: "openTun: provider gone"])
        }

        let settings = NEPacketTunnelNetworkSettings(tunnelRemoteAddress: "127.0.0.1")
        settings.mtu = NSNumber(value: options.getMTU())

        if let dnsServer = try? options.getDNSServerAddress() {
            let dns = NEDNSSettings(servers: [dnsServer.value])
            dns.matchDomains = [""]
            settings.dnsSettings = dns
        }

        var addresses: [String] = []
        var masks: [String] = []
        if let it = options.getInet4Address() {
            while it.hasNext() {
                guard let prefix = it.next() else { break }
                addresses.append(prefix.address())
                masks.append(prefix.mask())
            }
        }
        if !addresses.isEmpty {
            let ipv4 = NEIPv4Settings(addresses: addresses, subnetMasks: masks)
            var routes: [NEIPv4Route] = []
            if let it = options.getInet4RouteAddress(), it.hasNext() {
                while it.hasNext() {
                    guard let prefix = it.next() else { break }
                    routes.append(NEIPv4Route(destinationAddress: prefix.address(),
                                              subnetMask: prefix.mask()))
                }
            } else if options.getAutoRoute() {
                routes.append(NEIPv4Route.default())
            }
            var excluded: [NEIPv4Route] = []
            if let it = options.getInet4RouteExcludeAddress() {
                while it.hasNext() {
                    guard let prefix = it.next() else { break }
                    excluded.append(NEIPv4Route(destinationAddress: prefix.address(),
                                                subnetMask: prefix.mask()))
                }
            }
            ipv4.includedRoutes = routes
            ipv4.excludedRoutes = excluded
            settings.ipv4Settings = ipv4
        }

        var v6Addresses: [String] = []
        var v6Prefixes: [NSNumber] = []
        if let it = options.getInet6Address() {
            while it.hasNext() {
                guard let prefix = it.next() else { break }
                v6Addresses.append(prefix.address())
                v6Prefixes.append(NSNumber(value: prefix.prefix()))
            }
        }
        if !v6Addresses.isEmpty {
            let ipv6 = NEIPv6Settings(addresses: v6Addresses, networkPrefixLengths: v6Prefixes)
            var routes: [NEIPv6Route] = []
            if let it = options.getInet6RouteAddress(), it.hasNext() {
                while it.hasNext() {
                    guard let prefix = it.next() else { break }
                    routes.append(NEIPv6Route(destinationAddress: prefix.address(),
                                              networkPrefixLength: NSNumber(value: prefix.prefix())))
                }
            } else if options.getAutoRoute() {
                routes.append(NEIPv6Route.default())
            }
            ipv6.includedRoutes = routes
            settings.ipv6Settings = ipv6
        }

        // setTunnelNetworkSettings is async; libbox expects openTun to return
        // only when the tun is usable — block on a semaphore.
        let semaphore = DispatchSemaphore(value: 0)
        var settingsError: Error?
        provider.setTunnelNetworkSettings(settings) { error in
            settingsError = error
            semaphore.signal()
        }
        semaphore.wait()
        if let settingsError {
            throw settingsError
        }

        guard let fd = tunnelFileDescriptor else {
            throw NSError(domain: "ProxysVPN", code: 3,
                          userInfo: [NSLocalizedDescriptionKey: "could not locate tun file descriptor"])
        }
        ret0_?.pointee = fd
    }

    /// The utun fd behind packetFlow, which sing-box reads and writes
    /// directly. NetworkExtension does not expose it, so scan the open fds for
    /// a kernel-control socket whose interface name is utunN. The headers
    /// that define these two constants (<sys/sys_domain.h>, <net/if_utun.h>)
    /// are not visible to Swift on iOS, hence the literals.
    private var tunnelFileDescriptor: Int32? {
        let sysprotoControl: Int32 = 2 // SYSPROTO_CONTROL
        let utunOptIfname: Int32 = 2 // UTUN_OPT_IFNAME
        var name = [CChar](repeating: 0, count: Int(IFNAMSIZ))
        for fd: Int32 in 0...1024 {
            var len = socklen_t(name.count)
            guard getsockopt(fd, sysprotoControl, utunOptIfname, &name, &len) == 0 else {
                continue
            }
            let bytes = name.prefix { $0 != 0 }.map { UInt8(bitPattern: $0) }
            if String(decoding: bytes, as: UTF8.self).hasPrefix("utun") {
                return fd
            }
        }
        return nil
    }

    // MARK: Interface control

    // Swift imports gomobile's usePlatformAutoDetectInterfaceControl and
    // autoDetectInterfaceControl:error: under these shortened names.
    func usePlatformAutoDetectControl() -> Bool {
        true
    }

    func autoDetectControl(_: Int32) throws {
        // No-op: the system routes the extension's own sockets around the
        // tunnel automatically, no explicit bind needed on iOS.
    }

    // MARK: Default interface monitor

    func usePlatformDefaultInterfaceMonitor() -> Bool {
        true
    }

    func startDefaultInterfaceMonitor(_ listener: LibboxInterfaceUpdateListenerProtocol?) throws {
        guard let listener else { return }
        let monitor = NWPathMonitor()
        monitor.pathUpdateHandler = { path in
            guard path.status != .unsatisfied,
                  let iface = path.availableInterfaces.first
            else { return }
            listener.updateDefaultInterface(
                iface.name,
                interfaceIndex: Int32(iface.index),
                isExpensive: path.isExpensive,
                isConstrained: path.isConstrained
            )
        }
        monitor.start(queue: DispatchQueue(label: "com.proxysvpn.desktop.interface-monitor"))
        networkMonitor = monitor
    }

    func closeDefaultInterfaceMonitor(_: LibboxInterfaceUpdateListenerProtocol?) throws {
        networkMonitor?.cancel()
        networkMonitor = nil
    }

    // MARK: Interface enumeration

    func usePlatformInterfaceGetter() -> Bool {
        // Let Go's net package enumerate interfaces (works in the NE sandbox).
        false
    }

    func getInterfaces() throws -> LibboxNetworkInterfaceIteratorProtocol {
        throw NSError(domain: "ProxysVPN", code: 4,
                      userInfo: [NSLocalizedDescriptionKey: "platform interface getter disabled"])
    }

    // MARK: Process/package queries (Android/Linux only)

    func useProcFS() -> Bool {
        false
    }

    func findConnectionOwner(_: Int32, sourceAddress _: String?, sourcePort _: Int32,
                             destinationAddress _: String?, destinationPort _: Int32,
                             ret0_: UnsafeMutablePointer<Int32>?) throws {
        _ = ret0_
        throw NSError(domain: "ProxysVPN", code: 5,
                      userInfo: [NSLocalizedDescriptionKey: "findConnectionOwner not supported on iOS"])
    }

    // A _Nonnull NSString return with an NSError** is imported without
    // `throws`, so the error goes out through the pointer.
    func packageName(byUid _: Int32, error: NSErrorPointer) -> String {
        error?.pointee = NSError(domain: "ProxysVPN", code: 5,
                                 userInfo: [NSLocalizedDescriptionKey: "packageNameByUid not supported on iOS"])
        return ""
    }

    func uid(byPackageName _: String?, ret0_: UnsafeMutablePointer<Int32>?) throws {
        _ = ret0_
        throw NSError(domain: "ProxysVPN", code: 5,
                      userInfo: [NSLocalizedDescriptionKey: "uidByPackageName not supported on iOS"])
    }

    // MARK: Environment

    func underNetworkExtension() -> Bool {
        true
    }

    func includeAllNetworks() -> Bool {
        false
    }

    func clearDNSCache() {
        // Toggling reasserting forces the system to flush cached DNS state.
        guard let provider else { return }
        provider.reasserting = true
        provider.reasserting = false
    }

    func readWIFIState() -> LibboxWIFIState? {
        // Needs the Access WiFi Information entitlement + location permission;
        // not required for our routing rules.
        nil
    }

    // MARK: Misc

    func writeLog(_ message: String?) {
        guard let message else { return }
        os_log("%{public}@", log: tunnelLog, type: .info, message)
    }

    func send(_: LibboxNotification?) throws {
        // The app UI reflects state via NEVPNStatus; no local notifications.
    }

    func localDNSTransport() -> LibboxLocalDNSTransportProtocol? {
        nil
    }

    func systemCertificates() -> LibboxStringIteratorProtocol? {
        nil
    }
}
